                local parameters = {
                    gachaCoinLevel = checkInt(homeData.copyLevel),
                    gachaCoinAmount = checkInt(homeData.goodsSum),
                    gachaCoinCd = checkInt(homeData.timeLeft),
                    gachaCoinGoodsId = GCQConstants.Defines.GachaCoinGoodsId,
                    passedQuestId = checkInt(homeData.newPassedCopyId),
                    currentQuestId = checkInt(homeData.currentId),
                    currentQuestHpPercent = checkNumber(homeData.bossHpPercent),
                    currentChallengeTaskData = checkTable(homeData.copyChallengeInfo)
                }
                self:HandleArgument(parameters)
                self:Init()
            end
        end)
    end))
    return coWait
end

