--获取当前应该显示的关卡类型和id(有本地数据影响)
function GachaCoinQuestDialog:GetCurTypeAndLevelId()
    local gachaCoinQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.GachaCoinQuestComponent)
    local curLevelId = gachaCoinQuestComponent:GetCurChallengeLevel()
    local curLevelType = GoodsUtils.GetIdType(curLevelId, Constants.IDArea.Quests)
    --如果有本地缓存
    if curLevelId then
        if curLevelType == Constants.IDType.QuestGachaCoin then
            return GCQConstants.Defines.QuestType.Normal, curLevelId
        elseif curLevelType == Constants.IDType.QuestGachaCoinChallenge then
            return GCQConstants.Defines.QuestType.Challenge, curLevelId
        end   
    end

    curLevelId = self:CalcCurrentQuestId()
    curLevelType = GoodsUtils.GetIdType(curLevelId, Constants.IDArea.Quests)
    if curLevelType == Constants.IDType.QuestGachaCoin then
        return GCQConstants.Defines.QuestType.Normal, curLevelId
    elseif curLevelType == Constants.IDType.QuestGachaCoinChallenge then
        return GCQConstants.Defines.QuestType.Challenge, curLevelId
    end   
    return GCQConstants.Defines.QuestType.Normal, curLevelId
end

