---InitQuestListView 初始化列表
function GachaCoinQuestDialog:InitQuestListView()
    ---@field curQuestIds table 当前所有列表的id集合
    self.curQuestIds = {
        [GCQConstants.Defines.QuestType.Normal] = {},
        [GCQConstants.Defines.QuestType.Challenge] = {},
    }

    ---@field selectedIndex table 选中的序号
    self.selectedIndex = {
        [GCQConstants.Defines.QuestType.Normal] = nil,
        [GCQConstants.Defines.QuestType.Challenge] = nil
    }

    -- 初始化列表使用的数据
    local config = {
        GCQConstants.Defines.QuestType.Normal,
        GCQConstants.Defines.QuestType.Challenge
    }

    local allQuests = nil
    for _, questType in ipairs(config) do
        allQuests = GCQUtils.GetAllGachaCoinQuest(questType)
        ---@type GachaCoinQuestVo[]
        local allQuestsInfo = allQuests:GetAll()
        for _, questInfo in ipairs(allQuestsInfo) do
            table.insert(self.curQuestIds[questType], checkInt(questInfo.id))
        end
    end
    if not KTool.IsNull(self.QuestListView) and not self.isInit then
        self.isInit = true
        self.QuestListView:InitListView(0, Bind(self, self.OnGetQuestItemByIndex))
    end
end

