---RefreshQuestListView 刷新任务列表
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@param force boolean @ 强制刷新
function GachaCoinQuestDialog:RefreshQuestListView(questType, force)
    if self:GetCurQuestType() == questType and true ~= force then
        return
    end

    -- 刷新列表数据
    self:RefreshAllQuestData(questType)

    -- 刷新列表
    GameUtils.ReloadData(self.QuestListView, self:GetQuestAmount())
end

---RefreshQuestDetail 刷新关卡详情
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前挑战的关卡id
---@param passedQuestId integer @ 过关的关卡id
function GachaCoinQuestDialog:RefreshQuestDetail(questId, currentQuestId, passedQuestId)
    -- 刷新关卡详情
    self.QuestDetailScript:RefreshQuestDetail(questId, currentQuestId, self:GetHpPercentByQuestId(questId))
    -- 刷新战斗按钮
    self.BattleButtonScript:RefreshView(questId, currentQuestId, passedQuestId)
    -- 刷新关卡模式
    self.ModeChangeScript:RefreshByQuestId(questId, passedQuestId)
    -- 刷新挑战模式任务信息
    self.ChallengeTasksScript:RefreshView(questId, self:GetChallengeTaskInfoByQuestId(questId))
    -- 刷新背景板
    self.BgControllScript:RefreshView(questId)
    -- 刷新标题版
    self.TitleInfoScript:RefreshActiveStatus(questId)
end

---ChangeQuestType 变更关卡模式
---@param targetQuestType GachaCoinQuestConstants.Defines.QuestType 切换的目标关卡类型
function GachaCoinQuestDialog:ChangeQuestType(targetQuestType)
    -- 计算目标关卡
    local selectedQuestId = self:GetSelectedQuestId()
    local targetQuestId = nil
    if GCQConstants.Defines.QuestType.Normal == targetQuestType then
        targetQuestId = GCQUtils.GetNQuestIdByCQuestId(selectedQuestId)
    elseif GCQConstants.Defines.QuestType.Challenge == targetQuestType then
        targetQuestId = GCQUtils.GetCQuestIdByNQuestId(selectedQuestId)
    end
    -- 判断目标关卡是否解锁
    local unlock = self:IsQuestUnlock(targetQuestId)
    if not unlock then
        GameUtils.Toast(localize('未通过该关卡 无法进入挑战模式'))
    else
        self.BgControllScript:PlayDrawMoveAnimator(targetQuestType)
        -- 刷新界面
        self:RefreshViewByQuestType(targetQuestType, targetQuestId, true, true, nil == self:GetSelectedQuestId(targetQuestType))
    end
end

---RefreshViewByQuestType 根据关卡类型刷新界面
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@param questId integer @ 关卡id
---@param force boolean @ 强制刷新
---@param immediately boolean @ 立即刷新不带动画
---@param firstInit boolean @ 第一次初始化调用
function GachaCoinQuestDialog:RefreshViewByQuestType(questType, questId, force, immediately, firstInit)
    if self:GetCurQuestType() == questType and true ~= force then
        return
    end

    -- 根据类型刷新关卡列表
    self:RefreshQuestListView(questType, force)
    -- 跳转至目标关卡 刷新中间详情
    self:Jump2QuestByQuestId(questId, force, immediately, firstInit)
end


