---OnGetQuestItemByIndex 列表cell刷新回调
function GachaCoinQuestDialog:OnGetQuestItemByIndex(listView, index)
    if 0 > index then
        return
    end

    local questAmount = self:GetQuestAmount()
    local idx = index + 1
    if questAmount < idx then
        return
    end

    local cell = listView:NewListViewItem(GCQConstants.QuestListCellPrefab)
    local item = GetLuaBehaviour(cell.gameObject, GCQConstants.Path.QuestCellItemScript)

    if not IsNull(item) then
    --------补一个空位，用于Cell的完全显示(底部被遮住了)
        if index + 1 == questAmount then
            item.Env:SetEmptyStatus(true)
            return cell
        end
    -------------
        if not cell.IsInitHandlerCalled then
            -- 初始化item
            cell.IsInitHandlerCalled = true
            item:Init()
            item.Env:SetCellClickHandler(Bind(self, self.SelectCellByQuestId))
        end
        item.Env:SetEmptyStatus(false)

        -- 刷新cell样式
        ---@type GachaCoinQuestCellItem
        local itemScript = item.Env

        if not IsNull(itemScript) then

            local questId = self:GetQuestIdByIndex(idx)
            local unlock = self:IsQuestUnlock(questId)
            local selected = self:IsCellSelected(idx)
            local scale = self:CalcListCellScale(idx)

            itemScript:RefreshCell(questId, selected, unlock, scale)

        end

    end

    return cell
end

