---SelectCellByQuestId 根据关卡id选中格子
---@param questId integer @ 关卡id
function GachaCoinQuestDialog:SelectCellByQuestId(questId)
    -- 先判断是否可以选中该格子
    if not self:IsQuestUnlock(questId) then
        -- 没有解锁 跳提示
        local warningTxt = localize(string.format('尚未解锁该关卡'))
        GameUtils.Toast(warningTxt)
        return
    else
        -- 解锁了该关卡 跳转
        self.BgControllScript:RefreshView(questId)
        self:SelectedCellJumpByQuestId(questId, false, false)
        self.BgControllScript:PlayDrawChangeAnimator()
    end
end

