---SelectedCellJumpAnimationStart 开始带动画的格子选中跳转
---@param questId integer @ 关卡id
function GachaCoinQuestDialog:SelectedCellJumpAnimationStart(questId)
    if self:GetSelectedQuestId() == questId then return end

    -- 屏蔽触摸
    UIRaycastBlocker.Instance:AddCondition(GCQConstants.Defines.AniBlockerMark)

    -- 停掉列表移动
    self.QuestListView.ScrollRect:StopMovement()
    
    local currentIndex = self:GetSelectedCellIndex()
    local targetIndex = self:GetIndexByQuestId(questId)

    -- 计算需要做动画的格子的序号
    local deltaIndex = targetIndex - currentIndex
    local step = deltaIndex / Mathf.Abs(deltaIndex)
    local itor = 0
    local startCellIndex = nil
    local cellItem = nil
    
    local moveSpeedOneCell = 0.2
    local MaxScale = ListScalePattern[0]

    for i = currentIndex, targetIndex, step do

        cellItem = self.QuestListView:GetShownItemByItemIndex(i - 1)

        if not IsNull(cellItem) then

            ---@type GachaCoinQuestCellItem
            local cellItemScript = GetLuaBehaviour(cellItem.gameObject, GCQConstants.Path.QuestCellItemScript).Env
            local targetScale = self:CalcListCellScale(i, targetIndex)
            if nil == startCellIndex then
                startCellIndex = i
            end

            ------------ 格子动画 ------------
            -- 格子本身缩放动画分两步
            -- 1 变大到选中状态
            -- 2 缩小到目标状态
            if i == currentIndex then
                -- 隐藏格子选中底
                cellItemScript:RefreshCellSelected(false)
                cellItemScript.QuestNoLabel.gameObject.transform:DOScale(
                    Vector3.New(targetScale, targetScale, 1), moveSpeedOneCell
                )
                -- 处理上下其他格子的缩放
                for index, value in pairs(ListScalePattern) do
                    if 0 ~= index then
                        local otherIndex = i - step * index
                        local cellItem_ = self.QuestListView:GetShownItemByItemIndex(otherIndex - 1)
                        if not IsNull(cellItem_) then
                            local cellItemScript_ = GetLuaBehaviour(cellItem_.gameObject, GCQConstants.Path.QuestCellItemScript).Env
                            local scale = self:CalcListCellScale(otherIndex, targetIndex)
                            cellItemScript_.QuestNoLabel.gameObject.transform:DOScale(
                                Vector3.New(scale, scale, 1), moveSpeedOneCell
                            )
                        end
                    end
                end
            else
                cellItemScript.QuestNoLabel.gameObject.transform:DOScale(
                    Vector3.New(MaxScale, MaxScale, 1), moveSpeedOneCell
                ):SetDelay(
                    (itor - 1) * moveSpeedOneCell
                ):OnComplete(function ()
                    if i == targetIndex then
                        -- 处理上下其他格子的缩放
                        for index, value in pairs(ListScalePattern) do
                            if 0 ~= index then
                                local otherIndex = i + step * index
                                local cellItem_ = self.QuestListView:GetShownItemByItemIndex(otherIndex - 1)
                                if not IsNull(cellItem_) then
                                    local cellItemScript_ = GetLuaBehaviour(cellItem_.gameObject, GCQConstants.Path.QuestCellItemScript).Env
                                    cellItemScript_.QuestNoLabel.gameObject.transform:DOScale(
                                        Vector3.New(value, value, 1), moveSpeedOneCell
                                    )
                                end
                            end
                        end

                        -- 处理选中状态
                        -- 设置选中的序号
                        self:SetSelectedCellIndex(targetIndex)
                        -- 刷新关卡详情
                        self:RefreshQuestDetail(questId, self:GetCurQuestId(), self:GetPassedQuestId())--立绘
                        -- 显示格子选中底
                        cellItemScript:RefreshCellSelected(true)


                        -- 解除触摸屏蔽
                        UIRaycastBlocker.Instance:RemoveCondition(GCQConstants.Defines.AniBlockerMark)
                    else
                        cellItemScript.QuestNoLabel.gameObject.transform:DOScale(
                            Vector3.New(targetScale, targetScale, 1), moveSpeedOneCell
                        )
                    end
                end)
            end
            ------------ 格子动画 ------------
            itor = itor + 1
        end
    end

    ------------ 选中底的动画 ------------
    -- 刷新一下动画格
    KTool.SetActive(self.AnimationBg.gameObject, true)
    self.AniControllScript:RefreshAnimtionBgByQuestId(self:GetSelectedQuestId())

    -- 计算起始位置
    local fixPos = Vector3(0, 0, 0)
    local startCellItem = self.QuestListView:GetShownItemByItemIndex(startCellIndex - 1)
    local startPosWorld = startCellItem.gameObject.transform.parent.transform:TransformPoint(
        startCellItem:GetComponent(RectTransform_).anchoredPosition.x,
        startCellItem:GetComponent(RectTransform_).anchoredPosition.y,
        0
    )
    local startPosLocal = self.AnimationBg.parent.transform:InverseTransformPoint(startPosWorld)
    self.AnimationBg.gameObject:GetComponent(RectTransform_).anchoredPosition = Vector2.New(
        startPosLocal.x + fixPos.x, startPosLocal.y + fixPos.y
    )

    -- 计算目标格子位置
    local targetCellItem = self.QuestListView:GetShownItemByItemIndex(targetIndex - 1)
    local targetPosWorld = targetCellItem.gameObject.transform.parent.transform:TransformPoint(
        targetCellItem:GetComponent(RectTransform_).anchoredPosition.x,
        targetCellItem:GetComponent(RectTransform_).anchoredPosition.y,
        0
    )
    local targetPosLocal = self.AnimationBg.parent.transform:InverseTransformPoint(targetPosWorld)

    -- 动画
    self.AnimationBg.transform:DOLocalMoveY(
        targetPosLocal.y + fixPos.y,
        moveSpeedOneCell * (itor - 1)
    ):OnComplete(function ()
        -- 隐藏
        KTool.SetActive(self.AnimationBg.gameObject, false)
    end)
    ------------ 选中底的动画 ------------
end

---SelectedCellJumpImmediately 立即跳转选中格子 不做动画
---@param questId integer @ 关卡id
---@param force boolean @ 是否强制刷新
function GachaCoinQuestDialog:SelectedCellJumpImmediately(questId, force)
    local preSelectIdx = self:GetSelectedCellIndex()
    local targetIdx = self:GetIndexByQuestId(questId)

    if nil ~= preSelectIdx and preSelectIdx == targetIdx and not force then return end

    ------------ 上一个被选中的格子 ------------
    if nil ~= preSelectIdx then
        local preCell = self.QuestListView:GetShownItemByIndex(preSelectIdx - 1)
        local preCellScript = GCQUtils.GetCellScript(preCell)
        if not IsNull(preCellScript) then
            preCellScript:RefreshCellSelected(false)
        end
    end
    ------------ 上一个被选中的格子 ------------

    ------------ 目标格子 ------------
    local targetCell = self.QuestListView:GetShownItemByIndex(targetIdx - 1)
    local targetCellScript = GCQUtils.GetCellScript(targetCell)
    if not IsNull(targetCellScript) then
        targetCellScript:RefreshCellSelected(true)
    end
    ------------ 目标格子 ------------

    -- 设置选中的序号
    self:SetSelectedCellIndex(targetIdx)

    -- 刷新关卡详情
    self:RefreshQuestDetail(questId, self:GetCurQuestId(), self:GetPassedQuestId())
end


