---IsQuestUnlock 根据关卡id判断关卡是否解锁
---@param questId integer @ 关卡id
---@return boolean @ 是否解锁
function GachaCoinQuestDialog:IsQuestUnlock(questId)
    return GCQUtils.IsQuestUnlock(questId, self:GetPassedQuestId())
end

---IsCellSelected 判断cell是否被选中
---@param index integer @ 目标cell的index
---@return boolean @ 目标cell是否被选中
function GachaCoinQuestDialog:IsCellSelected(index)
    local selectedIndex = self:GetSelectedCellIndex()
    if not isNull(selectedIndex) and index == selectedIndex then
        return true
    else
        return false
    end
end

---CalcNewestQuestId 计算当前关卡id
---@return integer @ 当前关卡id
function GachaCoinQuestDialog:CalcCurrentQuestId()
    local currentQuestId = self:GetCurQuestId()
    if nil == currentQuestId or 0 == currentQuestId then
        -- 如果当前没有正在挑战的关卡 返回最新的关卡id
        local passedQuestId = self:GetPassedQuestId()
        if 0 == passedQuestId then
            currentQuestId = GCQUtils.GetFirstQuestId()
        else
            currentQuestId = passedQuestId + 1
        end
        -- 检查是否打穿了整个副本
        local index = self:GetIndexByQuestId(currentQuestId)
        if nil == index then
            currentQuestId = self:GetLastQuestId()
        end
    end
    return currentQuestId
end


