-- events begin --
---------------------------------------------------

---InitEvents 初始化事件
function GachaCoinQuestDialog:InitEvents()
    -- 放弃关卡
    if nil == self.giveUpQuestCallback_ then
        self.giveUpQuestCallback_ = Bind(self, self.GiveUpQuestCallback)
        Events.AddListener(Constants.EventNames.GachaCoinQuestGiveUpQuest, self.giveUpQuestCallback_)
    end

    -- 领取任务奖励
    if nil == self.challengeTaskDrawRewardsCallback_ then
        self.challengeTaskDrawRewardsCallback_ = Bind(self, self.ChallengeTaskDrawRewardsCallback)
        Events.AddListener(Constants.EventNames.GachaCoinQuestTaskDrawRewards, self.challengeTaskDrawRewardsCallback_)
    end
end

---UnregistEvents 注销事件监听
function GachaCoinQuestDialog:UnregistEvents()
    -- 放弃关卡
    if nil ~= self.giveUpQuestCallback_ then
        Events.RemoveListener(Constants.EventNames.GachaCoinQuestGiveUpQuest, self.giveUpQuestCallback_)
        self.giveUpQuestCallback_ = nil
    end

    if nil ~= self.challengeTaskDrawRewardsCallback_ then
        Events.RemoveListener(Constants.EventNames.GachaCoinQuestTaskDrawRewards, self.challengeTaskDrawRewardsCallback_)
        self.challengeTaskDrawRewardsCallback_ = nil
    end
end

---GiveUpQuestCallback 放弃关卡回调 
function GachaCoinQuestDialog:GiveUpQuestCallback()
    -- 重置当前关卡
    self:SetCurQuestId(0)
    -- 重置boss血量
    self:ResetQuestHpPercent()
    -- 刷新界面
    self:RefreshQuestDetail(
        self:GetSelectedQuestId(),
        self:GetCurQuestId(),
        self:GetPassedQuestId()
    )
end

---ChallengeTaskDrawRewardsCallback 挑战模式关卡领取任务奖励
---@param eventData table 传参
function GachaCoinQuestDialog:ChallengeTaskDrawRewardsCallback(eventData)
    -- 刷新数据
    self:SetChallengeTaskState(
        eventData.questId, eventData.taskId, eventData.taskState
    )
end


---------------------------------------------------
-- get set begin --
---------------------------------------------------

---GetCurQuestId 获取当前正在挑战的关卡id
---@return integer @ 正在挑战的关卡id
function GachaCoinQuestDialog:GetCurQuestId()
    return self.currentQuestId
end
function GachaCoinQuestDialog:SetCurQuestId(questId)
    self.currentQuestId = questId
end

---获取当前选择的关卡类型
---@return GachaCoinQuestConstants.Defines.QuestType 抽卡道具副本关卡类型
function GachaCoinQuestDialog:GetCurQuestType()
    return self.currentQuestType
end
function GachaCoinQuestDialog:SetCurQuestType(questType)
    self.currentQuestType = questType
end

---GetQuestIdByIndex 根据列表序号获取关卡id
---@param index integer @ 列表序号
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@return integer @ 关卡id
function GachaCoinQuestDialog:GetQuestIdByIndex(index, questType)
    local qt_ = questType or self:GetCurQuestType()
    return self.curQuestIds[qt_][index]
end

---GetQuestAmount 获取当前类型关卡的数量
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@return integer @ 关卡数量
function GachaCoinQuestDialog:GetQuestAmount(questType)
    local qt_ = questType or self:GetCurQuestType()
    local emptyNodeCount = 1 --补一个空位，用于Cell的完全显示(底部被遮住了)
    return not isNull(next(self.curQuestIds[qt_])) and #self.curQuestIds[qt_] + emptyNodeCount or 0
end

---GetPassedQuestId 获取打通的最新关卡id
---@return integer @ 打通的关卡id
function GachaCoinQuestDialog:GetPassedQuestId()
    return self.passedQuestId
end

---GetSelectedCellIndex 获取选中的cell序号
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@return integer @ 选中的cell序号
function GachaCoinQuestDialog:GetSelectedCellIndex(questType)
    local qt_ = questType or self:GetCurQuestType()
    return self.selectedIndex[qt_]
end
function GachaCoinQuestDialog:SetSelectedCellIndex(index, questType)
    local qt_ = questType or self:GetCurQuestType()
    self.selectedIndex[qt_] = index
end
---GetSelectedQuestId 获取选中的关卡id
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@return integer @ 关卡id
function GachaCoinQuestDialog:GetSelectedQuestId(questType)
    local qt_ = questType or self:GetCurQuestType()
    local index = self:GetSelectedCellIndex(qt_)
    local questId = self:GetQuestIdByIndex(index, qt_)
    return questId
end

---GetIndexByQuestId 根据关卡id获取cell序号
---@param questId integer @ 关卡id
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@return integer @ 关卡序号
function GachaCoinQuestDialog:GetIndexByQuestId(questId, questType)
    local qt_ = questType or self:GetCurQuestType()
    for index, questId_ in ipairs(self.curQuestIds[qt_]) do
        if questId_ == questId then
            return index
        end
    end
    return nil
end

---GetLastQuestId 获取最后一关的关卡id
---@param questType GachaCoinQuestConstants.Defines.QuestType 关卡类型
---@return integer @ 关卡id
function GachaCoinQuestDialog:GetLastQuestId(questType)
    local qt_ = questType or self:GetCurQuestType()
    return self.curQuestIds[qt_][#self.curQuestIds[qt_]]
end

---GetHpPercentByQuestId 根据关卡id获取关卡血量百分比
---@param questId integer @ 关卡id
---@return number 当前关卡的血量百分比
function GachaCoinQuestDialog:GetHpPercentByQuestId(questId)
    local currentQuestId = self:GetCurQuestId()
    if isNull(currentQuestId) or questId ~= currentQuestId then
        return 1
    else
        return self.currentQuestHpPercent
    end
end

---ResetQuestHpPercent 重置任务血量
function GachaCoinQuestDialog:ResetQuestHpPercent()
    self.currentQuestHpPercent = 1
end

---GetChallengeTaskState 获取挑战模式关卡任务状态
---@param questId integer @ 关卡id
---@param taskId integer @ 任务id
function GachaCoinQuestDialog:GetChallengeTaskState(questId, taskId)
    return self:GetChallengeTaskInfoByQuestId(questId)[tostring(taskId)]
end
function GachaCoinQuestDialog:SetChallengeTaskState(questId, taskId, taskState)
    if nil == self.currentChallengeTaskData[tostring(questId)] then
        self.currentChallengeTaskData[tostring(questId)] = {}
    end
    self.currentChallengeTaskData[tostring(questId)][tostring(taskId)] = taskState
end
---GetChallengeTaskInfoByQuestId 根据关卡id获取任务信息
---@param questId integer @ 关卡id
---@return table 挑战关卡任务信息
function GachaCoinQuestDialog:GetChallengeTaskInfoByQuestId(questId)
    return self.currentChallengeTaskData[tostring(questId)] or {}
end


return GachaCoinQuestDialog